with content as (select * from jsonb_to_recordset($senior_content$[{"source_id":219,"word":"abolish","example":"Our school decided to abolish the rule requiring students to wear ties.","example_zh":"我們學校決定廢除要求學生打領帶的規定。","original_example":"The law was abolished.","original_example_zh":"該法律已被廢除。"},{"source_id":220,"word":"abstract","example":"The artist used abstract shapes to express her feelings.","example_zh":"這位藝術家用抽象的形狀表達她的感受。","original_example":"Art can be abstract.","original_example_zh":"藝術可以是抽象的。"},{"source_id":224,"word":"adequate","example":"We packed adequate food and water for our one-day hike.","example_zh":"我們為一天的健行準備了足夠的食物和飲水。","original_example":"We need adequate preparation.","original_example_zh":"我們需要充分的準備。"},{"source_id":228,"word":"analyze","example":"We analyze the water samples to find the source of pollution.","example_zh":"我們分析水樣，以找出污染來源。","original_example":"We need to analyze the data.","original_example_zh":"我們需要分析資料。"},{"source_id":231,"word":"apparently","example":"Apparently, someone left the window open, because the floor is wet.","example_zh":"看來有人沒關窗，因為地板濕了。","original_example":"Apparently, he was right.","original_example_zh":"看來，他是對的。"},{"source_id":232,"word":"appropriate","example":"Closed shoes are appropriate for working in the science lab.","example_zh":"包鞋適合在科學實驗室裡穿。","original_example":"Use appropriate language.","original_example_zh":"使用恰當的語言。"},{"source_id":234,"word":"associate","example":"I associate the smell of fresh bread with my grandmother's kitchen.","example_zh":"新鮮麵包的香味讓我聯想到祖母的廚房。","original_example":"I associate summer with vacation.","original_example_zh":"我總把夏天聯想到假期。"},{"source_id":240,"word":"circumstance","example":"Because of the circumstances, we moved our outdoor concert into the gym.","example_zh":"由於當時的情況，我們把戶外音樂會移到體育館。","original_example":"Under the circumstances, we had no choice.","original_example_zh":"在這種情況下，我們別無選擇。"},{"source_id":243,"word":"comprehensive","example":"Our class created a comprehensive guide to recycling at school.","example_zh":"我們班製作了一份全面的校園回收指南。","original_example":"A comprehensive report.","original_example_zh":"一份詳盡的報告。"},{"source_id":246,"word":"consequence","example":"A flooded classroom was the consequence of leaving the tap running.","example_zh":"忘記關水龍頭的後果是教室淹水。","original_example":"Every action has consequences.","original_example_zh":"每項行動都有後果。"},{"source_id":250,"word":"controversy","example":"The plan to cut down the old tree caused controversy in our town.","example_zh":"砍掉老樹的計畫在我們鎮上引發爭議。","original_example":"The policy caused controversy.","original_example_zh":"這項政策引發了爭議。"},{"source_id":253,"word":"crucial","example":"Checking the brakes is crucial before a long bike ride.","example_zh":"長途騎車前檢查煞車至關重要。","original_example":"This is a crucial moment.","original_example_zh":"這是關鍵時刻。"},{"source_id":255,"word":"demonstrate","example":"Our teacher will demonstrate how to use the microscope.","example_zh":"老師會示範如何使用顯微鏡。","original_example":"She demonstrated the technique.","original_example_zh":"她示範了這項技巧。"},{"source_id":262,"word":"eliminate","example":"Reusable lunch boxes help us eliminate disposable plastic bags.","example_zh":"可重複使用的餐盒幫助我們消除對一次性塑膠袋的需求。","original_example":"We must eliminate waste.","original_example_zh":"我們必須杜絕浪費。"},{"source_id":264,"word":"emerge","example":"A butterfly began to emerge from its chrysalis.","example_zh":"一隻蝴蝶開始從蛹中羽化而出。","original_example":"New evidence emerged.","original_example_zh":"新證據浮現。"},{"source_id":265,"word":"enormous","example":"An enormous whale swam beside our small boat.","example_zh":"一頭巨大的鯨魚游在我們的小船旁。","original_example":"An enormous building.","original_example_zh":"一座巨大的建築。"},{"source_id":272,"word":"facilitate","example":"The new ramp will facilitate access to the school library.","example_zh":"新設的坡道將方便大家進入學校圖書館。","original_example":"Technology facilitates learning.","original_example_zh":"科技促進學習。"},{"source_id":275,"word":"fundamental","example":"Learning to measure accurately is fundamental to a good science experiment.","example_zh":"學會精確測量是做好科學實驗的基礎。","original_example":"A fundamental problem.","original_example_zh":"一個根本性問題。"},{"source_id":276,"word":"genuine","example":"Her genuine smile showed how happy she was to see her friend.","example_zh":"她真誠的笑容顯示出見到朋友有多開心。","original_example":"A genuine smile.","original_example_zh":"發自內心的微笑。"},{"source_id":281,"word":"implement","example":"Our school will implement a new recycling program next month.","example_zh":"我們學校下個月將實施新的回收計畫。","original_example":"Implement the new policy.","original_example_zh":"實施新政策。"},{"source_id":292,"word":"phenomenon","example":"A rainbow is a natural phenomenon that often appears after rain.","example_zh":"彩虹是一種常在雨後出現的自然現象。","original_example":"A natural phenomenon.","original_example_zh":"一種自然現象。"},{"source_id":300,"word":"sophisticated","example":"The robot uses a sophisticated camera system to sort recyclable materials.","example_zh":"這台機器人用精密的攝影系統分類可回收物。","original_example":"This new phone has a very sophisticated camera system for amazing photos.","original_example_zh":"這款新手機配備了非常先進的相機系統，能拍攝出驚人的照片。"},{"source_id":303,"word":"substantial","example":"Our class collected a substantial amount of food for the shelter.","example_zh":"我們班為收容所募集了大量食物。","original_example":"A substantial amount.","original_example_zh":"一筆可觀的金額。"},{"source_id":304,"word":"sustainable","example":"Cycling to school is a sustainable way to travel.","example_zh":"騎自行車上學是一種永續的交通方式。","original_example":"Sustainable development.","original_example_zh":"永續發展。"},{"source_id":305,"word":"sympathy","example":"Mia showed sympathy by sitting beside her friend after his dog died.","example_zh":"朋友的狗過世後，米雅坐在他身旁，表達同情與關心。","original_example":"I have sympathy for them.","original_example_zh":"我對他們抱有同情。"},{"source_id":310,"word":"unprecedented","example":"The school saw unprecedented participation in this year's science fair.","example_zh":"今年學校科展的參與人數創下空前紀錄。","original_example":"The company experienced unprecedented growth this year, surprising everyone.","original_example_zh":"今年公司經歷了前所未有的成長，令所有人感到驚訝。"},{"source_id":759,"word":"alter","example":"We had to alter our model bridge to make it stronger.","example_zh":"我們必須修改橋梁模型，讓它更堅固。","original_example":"Do not alter the document.","original_example_zh":"請勿修改文件。"},{"source_id":791,"word":"component","example":"The battery is an essential component of this electric car.","example_zh":"電池是這輛電動車的重要組件。","original_example":"A key component.","original_example_zh":"關鍵組件。"},{"source_id":797,"word":"confront","example":"We must confront the problem of litter in our schoolyard.","example_zh":"我們必須面對校園裡亂丟垃圾的問題。","original_example":"Confront the challenge.","original_example_zh":"直面挑戰。"},{"source_id":808,"word":"convey","example":"Her drawing helped convey the importance of protecting sea turtles.","example_zh":"她的畫有助於傳達保護海龜的重要性。","original_example":"Convey the message.","original_example_zh":"傳達訊息。"},{"source_id":809,"word":"cooperate","example":"We must cooperate to carry the heavy table into the classroom.","example_zh":"我們必須合作，把沉重的桌子搬進教室。","original_example":"Nations must cooperate.","original_example_zh":"各國必須合作。"},{"source_id":831,"word":"dimension","example":"We measured each dimension of the box before building the model.","example_zh":"我們製作模型前，先測量盒子的每個尺寸。","original_example":"A new dimension.","original_example_zh":"一個新維度。"},{"source_id":841,"word":"distinct","example":"The two butterflies have distinct patterns on their wings.","example_zh":"這兩隻蝴蝶翅膀上的花紋明顯不同。","original_example":"Two distinct groups.","original_example_zh":"兩個截然不同的群體。"},{"source_id":843,"word":"diverse","example":"Our class shared dishes from diverse cultures at the school festival.","example_zh":"我們班在校慶時分享來自多元文化的料理。","original_example":"A diverse population.","original_example_zh":"一個多元化的族群。"},{"source_id":846,"word":"donate","example":"We donate warm clothes to families who need them each winter.","example_zh":"我們每年冬天都捐贈保暖衣物給有需要的家庭。","original_example":"He donated an etching from his own collection to the new art gallery.","original_example_zh":"他將自己收藏的一幅蝕刻版畫捐贈給新成立的藝術畫廊。"},{"source_id":853,"word":"efficient","example":"Our efficient team packed all the books before lunch.","example_zh":"我們這個有效率的團隊在午餐前就打包好所有書籍。","original_example":"An efficient system.","original_example_zh":"一個高效的系統。"},{"source_id":860,"word":"enhance","example":"Regular practice can enhance your ability to play the violin.","example_zh":"規律練習能增進你拉小提琴的能力。","original_example":"Enhance your skills.","original_example_zh":"提升你的技能。"},{"source_id":886,"word":"forbid","example":"The museum rules forbid visitors from touching the paintings.","example_zh":"博物館規定禁止遊客觸摸畫作。","original_example":"Smoking is forbidden here.","original_example_zh":"此處禁止吸菸。"},{"source_id":897,"word":"fulfill","example":"She worked hard to fulfill her dream of becoming a pilot.","example_zh":"她努力實現成為飛行員的夢想。","original_example":"Fulfill your dream.","original_example_zh":"實現你的夢想。"},{"source_id":900,"word":"globe","example":"The students used a globe to locate Taiwan.","example_zh":"學生們用地球儀找出台灣的位置。","original_example":"Around the globe.","original_example_zh":"環遊世界。"},{"source_id":906,"word":"guarantee","example":"The repair shop will guarantee the new battery for one year.","example_zh":"維修店會為這顆新電池提供一年的保固。","original_example":"I guarantee it will work.","original_example_zh":"我保證這會奏效。"},{"source_id":920,"word":"identical","example":"We wore identical jackets on the school trip.","example_zh":"我們在校外教學時穿著完全相同的外套。","original_example":"The twins are identical.","original_example_zh":"這對雙胞胎是同卵雙胞胎。"},{"source_id":927,"word":"impose","example":"The school will impose a fine for damaging library books.","example_zh":"學校會對損壞圖書館書籍的人處以罰款。","original_example":"Congress imposed new tariffs.","original_example_zh":"國會徵收了新關稅。"},{"source_id":931,"word":"indicate","example":"The dark clouds indicate that a storm may be approaching.","example_zh":"烏雲顯示暴風雨可能即將來臨。","original_example":"The data indicates a trend.","original_example_zh":"數據顯示出一種趨勢。"},{"source_id":942,"word":"insight","example":"Examining the roots gave us insight into why the plant was dying.","example_zh":"檢查根部讓我們了解這株植物為何逐漸枯萎。","original_example":"Gain valuable insights.","original_example_zh":"獲得寶貴的見解。"},{"source_id":944,"word":"inspire","example":"The astronaut's story helped inspire me to study science.","example_zh":"這位太空人的故事啟發我學習科學。","original_example":"She inspires others.","original_example_zh":"她激勵他人。"},{"source_id":950,"word":"interpret","example":"We learned to interpret the symbols on a hiking map.","example_zh":"我們學會解讀健行地圖上的符號。","original_example":"How do you interpret this?","original_example_zh":"你如何解讀這件事？"},{"source_id":958,"word":"isolate","example":"We isolate the sick plants to protect the healthy ones.","example_zh":"我們把生病的植物隔離，以保護健康的植物。","original_example":"Isolate the infected patients.","original_example_zh":"隔離受感染的病患。"},{"source_id":961,"word":"justify","example":"She used photos of the damage to justify replacing the old roof.","example_zh":"她用損壞處的照片證明更換舊屋頂是合理的。","original_example":"Justify your answer.","original_example_zh":"請說明你的答案。"},{"source_id":5122,"word":"absolute","example":"The students worked in absolute silence during the exam.","example_zh":"考試期間，學生們在完全安靜的環境中作答。","original_example":"Absolute power.","original_example_zh":"絕對權力。"},{"source_id":5123,"word":"accent","example":"Her Australian accent reminded me of my cousin in Sydney.","example_zh":"她的澳洲口音讓我想起住在雪梨的表姊。","original_example":"A British accent.","original_example_zh":"英國口音。"},{"source_id":5126,"word":"aid","example":"Volunteers delivered emergency aid after the flood.","example_zh":"洪水過後，志工運送緊急援助物資。","original_example":"Foreign aid.","original_example_zh":"外國援助。"},{"source_id":5128,"word":"aircraft","example":"The small aircraft landed safely on the island.","example_zh":"這架小飛機安全降落在島上。","original_example":"A military aircraft.","original_example_zh":"一架軍用飛機。"},{"source_id":5130,"word":"alert","example":"Stay alert when you cycle past a busy intersection.","example_zh":"騎車經過繁忙路口時，要保持警覺。","original_example":"Stay alert.","original_example_zh":"保持警覺。"},{"source_id":5131,"word":"alien","example":"The friendly alien offered to show us its spaceship.","example_zh":"友善的外星人主動帶我們參觀牠的太空船。","original_example":"An alien planet.","original_example_zh":"外星行星。"},{"source_id":5133,"word":"ally","example":"Our class found an ally in the teacher who supported our recycling plan.","example_zh":"我們班找到一位支持回收計畫的老師，成為我們的盟友。","original_example":"A political ally.","original_example_zh":"一位政治盟友。"},{"source_id":5136,"word":"apparent","example":"The damage to the bridge was apparent after the storm.","example_zh":"暴風雨過後，橋梁的損壞十分明顯。","original_example":"An apparent reason.","original_example_zh":"一個顯而易見的理由。"},{"source_id":5137,"word":"appeal","example":"The students appeal to the community for help cleaning the beach.","example_zh":"學生們呼籲社區協助清理海灘。","original_example":"Appeal for help.","original_example_zh":"呼籲協助。"},{"source_id":5138,"word":"appoint","example":"The teacher will appoint a leader for our science project.","example_zh":"老師會任命一位同學擔任科學專題的組長。","original_example":"Appoint a leader.","original_example_zh":"任命一位領導者。"},{"source_id":5139,"word":"approve","example":"The principal will approve our plan after checking the budget.","example_zh":"校長檢查預算後，將批准我們的計畫。","original_example":"Approve the plan.","original_example_zh":"批准該計畫。"},{"source_id":5142,"word":"assess","example":"We assess the damage before repairing the school garden.","example_zh":"我們修復校園花園前，先評估損壞情況。","original_example":"Assess the risk.","original_example_zh":"評估風險。"},{"source_id":5143,"word":"assure","example":"The coach tried to assure me that I was ready for the race.","example_zh":"教練試著向我保證，我已經準備好參加比賽。","original_example":"I assure you.","original_example_zh":"我向您保證。"},{"source_id":5146,"word":"avenue","example":"We walked along the tree-lined avenue after school.","example_zh":"放學後，我們沿著綠樹成蔭的大道散步。","original_example":"A tree-lined avenue.","original_example_zh":"一條綠樹成蔭的大道。"},{"source_id":5148,"word":"billion","example":"The museum's computer model showed a billion stars in our galaxy.","example_zh":"博物館的電腦模型呈現了銀河系中十億顆恆星。","original_example":"A billion dollars.","original_example_zh":"十億美元。"},{"source_id":5154,"word":"celebrity","example":"The celebrity visited our school to support the charity concert.","example_zh":"這位名人到我們學校支持慈善音樂會。","original_example":"A TV celebrity.","original_example_zh":"一位電視名人。"},{"source_id":5157,"word":"civil","example":"Our class discussed civil rights during the history lesson.","example_zh":"我們班在歷史課討論公民權利。","original_example":"Civil rights.","original_example_zh":"公民權利。"},{"source_id":5164,"word":"compose","example":"Lena likes to compose music for the school band.","example_zh":"莉娜喜歡為學校樂團作曲。","original_example":"Compose a song.","original_example_zh":"創作一首歌曲。"},{"source_id":5165,"word":"congress","example":"Congress debated the new environmental law for several hours.","example_zh":"國會花了幾個小時辯論新的環境法案。","original_example":"The US Congress.","original_example_zh":"美國國會。"},{"source_id":5166,"word":"considerable","example":"Restoring the old library required considerable time and effort.","example_zh":"修復這座老圖書館需要相當多的時間與心力。","original_example":"Considerable effort.","original_example_zh":"相當大的努力。"},{"source_id":5167,"word":"convert","example":"The device can convert sunlight into electricity.","example_zh":"這個裝置能把陽光轉換成電能。","original_example":"Convert currency.","original_example_zh":"兌換貨幣。"},{"source_id":5168,"word":"core","example":"At the core of our plan is a desire to reduce food waste.","example_zh":"我們計畫的核心是減少食物浪費。","original_example":"The core issue.","original_example_zh":"核心問題。"},{"source_id":5174,"word":"critic","example":"The film critic praised the young director's first movie.","example_zh":"這位影評人讚賞年輕導演的首部電影。","original_example":"A film critic.","original_example_zh":"一名影評人。"},{"source_id":5176,"word":"curve","example":"The road follows a gentle curve around the lake.","example_zh":"道路沿著湖邊緩緩彎曲。","original_example":"A learning curve.","original_example_zh":"學習曲線。"},{"source_id":5177,"word":"declare","example":"The judges will declare the winner after the final performance.","example_zh":"評審會在最後一場表演結束後宣布得獎者。","original_example":"Declare independence.","original_example_zh":"宣告獨立。"},{"source_id":5182,"word":"desperate","example":"We made a desperate search for our missing dog before sunset.","example_zh":"我們在日落前焦急地尋找走失的狗。","original_example":"A desperate attempt.","original_example_zh":"絕望的嘗試。"},{"source_id":5191,"word":"economic","example":"The new market brought economic benefits to the town.","example_zh":"新市場為這個小鎮帶來經濟效益。","original_example":"Economic growth.","original_example_zh":"經濟成長。"},{"source_id":5194,"word":"electronic","example":"Students must turn off electronic devices during the exam.","example_zh":"考試期間，學生必須關閉電子裝置。","original_example":"Electronic devices.","original_example_zh":"電子設備。"},{"source_id":5196,"word":"emphasis","example":"The coach placed emphasis on teamwork instead of individual scores.","example_zh":"教練特別強調團隊合作，而非個人得分。","original_example":"Place emphasis on.","original_example_zh":"強調。"},{"source_id":5198,"word":"equip","example":"The school will equip each science team with safety goggles.","example_zh":"學校將為每個科學小組配備護目鏡。","original_example":"Equip the team.","original_example_zh":"為團隊配備裝備。"},{"source_id":5206,"word":"export","example":"Local farmers export tea to customers around the world.","example_zh":"當地農民把茶葉出口到世界各地的顧客手中。","original_example":"Export goods.","original_example_zh":"出口商品。"},{"source_id":5207,"word":"external","example":"The external walls of the building need fresh paint.","example_zh":"這棟建築的外牆需要重新粉刷。","original_example":"External factors.","original_example_zh":"外部因素。"},{"source_id":5208,"word":"extraordinary","example":"Her extraordinary memory helped her recall every detail of the painting.","example_zh":"她非凡的記憶力讓她記起那幅畫的每一個細節。","original_example":"An extraordinary talent.","original_example_zh":"非凡的才華。"},{"source_id":5209,"word":"faith","example":"Her faith brought her comfort during a difficult time.","example_zh":"她的信仰在艱難時刻帶給她安慰。","original_example":"Have faith.","original_example_zh":"要有信心。"},{"source_id":5211,"word":"fascinate","example":"The glowing jellyfish never fail to fascinate me.","example_zh":"發光的水母總是讓我著迷。","original_example":"Fascinated by science.","original_example_zh":"對科學著迷。"},{"source_id":5216,"word":"fellow","example":"He is a fellow member of our school's astronomy club.","example_zh":"他是我們學校天文社的夥伴。","original_example":"A fellow student.","original_example_zh":"一位同學。"},{"source_id":5221,"word":"filter","example":"The filter traps small pieces of dirt in the water.","example_zh":"這個過濾器會攔住水中的細小髒汙。","original_example":"A water filter.","original_example_zh":"濾水器。"},{"source_id":5222,"word":"finance","example":"She hopes to study finance and help small businesses manage money.","example_zh":"她希望研讀金融，協助小企業管理資金。","original_example":"Corporate finance.","original_example_zh":"企業財務。"},{"source_id":5231,"word":"frequent","example":"Frequent practice helped our team improve its passing skills.","example_zh":"頻繁的練習幫助我們球隊提升傳球技巧。","original_example":"Frequent visits.","original_example_zh":"頻繁造訪。"},{"source_id":5240,"word":"immigrant","example":"The new immigrant opened a bakery in our neighborhood.","example_zh":"這位新移民在我們社區開了一間麵包店。","original_example":"An illegal immigrant.","original_example_zh":"一名非法移民。"},{"source_id":5243,"word":"inner","example":"A quiet walk helped her find inner peace after a stressful day.","example_zh":"忙碌緊張的一天後，安靜散步幫助她找回內心的平靜。","original_example":"Inner peace.","original_example_zh":"內心的平靜。"},{"source_id":5244,"word":"input","example":"The computer uses input from the keyboard to display the message.","example_zh":"電腦利用鍵盤輸入的資料來顯示訊息。","original_example":"Data input.","original_example_zh":"資料輸入。"},{"source_id":5246,"word":"insert","example":"Insert the memory card into the camera before taking photos.","example_zh":"拍照前，先把記憶卡插進相機。","original_example":"Insert the card.","original_example_zh":"插入卡片。"},{"source_id":5249,"word":"insurance","example":"Travel insurance helped cover the cost of her lost suitcase.","example_zh":"旅遊保險協助支付她遺失行李的損失。","original_example":"Health insurance.","original_example_zh":"健康保險。"},{"source_id":5250,"word":"interact","example":"The workshop gives students a chance to interact with visiting artists.","example_zh":"這場工作坊讓學生有機會和來訪的藝術家互動。","original_example":"Interact with others.","original_example_zh":"與他人互動。"},{"source_id":5257,"word":"journal","example":"We found an article about ocean pollution in a science journal.","example_zh":"我們在一本科學期刊中找到關於海洋污染的文章。","original_example":"An academic journal.","original_example_zh":"一份學術期刊。"},{"source_id":5272,"word":"literally","example":"Tom took 'break the ice' literally and reached for a hammer.","example_zh":"湯姆照字面理解「打破僵局」，於是伸手拿鐵鎚。","original_example":"Literally means.","original_example_zh":"字面意思是。"},{"source_id":5276,"word":"manual","example":"We used a manual pump to fill the bicycle tire.","example_zh":"我們用手動打氣筒替自行車輪胎充氣。","original_example":"A manual transmission.","original_example_zh":"手動變速箱。"},{"source_id":5278,"word":"mass","example":"The speaker used simple language to reach the masses.","example_zh":"這位講者用淺顯的語言向大眾傳達訊息。","original_example":"Mass media.","original_example_zh":"大眾媒體。"},{"source_id":5279,"word":"medium","example":"She chose clay as the medium for her art project.","example_zh":"她選擇以陶土作為藝術專題的媒材。","original_example":"Social medium.","original_example_zh":"社交媒介。"},{"source_id":5285,"word":"multiple","example":"We tested multiple designs before choosing the strongest bridge.","example_zh":"我們測試了多種設計，才選出最堅固的橋。","original_example":"Multiple choices.","original_example_zh":"多項選擇題。"}]$senior_content$::jsonb) as r(source_id bigint,word text,example text,example_zh text,original_example text,original_example_zh text))
update public.word_bank w set example=c.example,example_zh=c.example_zh from content c where w.id=c.source_id and w.level='senior' and w.word=c.word and (w.example,w.example_zh) is not distinct from (c.original_example,c.original_example_zh);
insert into public.word_illustrations(id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version)
select id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version from jsonb_to_recordset($senior_rows$[{"id":"senior-abolish-01-v1","level":"senior","word":"abolish","sort_order":1,"sense":"廢除","alt_zh":"老師從學校布告欄取下一張印有領帶圖示的規定海報，旁邊的高中生鬆開領帶。","example":"Our school decided to abolish the rule requiring students to wear ties.","example_zh":"我們學校決定廢除要求學生打領帶的規定。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/abolish-01-v1.webp","local_path":"/images/vocabulary/senior/abolish-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-abstract-01-v1","level":"senior","word":"abstract","sort_order":1,"sense":"抽象的","alt_zh":"高中生站在畫架旁，畫布上是沒有具體物件的彩色幾何形狀與筆觸。","example":"The artist used abstract shapes to express her feelings.","example_zh":"這位藝術家用抽象的形狀表達她的感受。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/abstract-01-v1.webp","local_path":"/images/vocabulary/senior/abstract-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-adequate-01-v1","level":"senior","word":"adequate","sort_order":1,"sense":"足夠的","alt_zh":"兩名高中生在登山口檢查背包，每人都有一份午餐與一瓶飲用水。","example":"We packed adequate food and water for our one-day hike.","example_zh":"我們為一天的健行準備了足夠的食物和飲水。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/adequate-01-v1.webp","local_path":"/images/vocabulary/senior/adequate-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-analyze-01-v1","level":"senior","word":"analyze","sort_order":1,"sense":"分析","alt_zh":"兩名高中生戴著護目鏡，比較試管中的水樣與桌上的檢測結果。","example":"We analyze the water samples to find the source of pollution.","example_zh":"我們分析水樣，以找出污染來源。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/analyze-01-v1.webp","local_path":"/images/vocabulary/senior/analyze-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-apparently-01-v1","level":"senior","word":"apparently","sort_order":1,"sense":"顯然","alt_zh":"高中生看著敞開的窗戶和窗邊地板上的雨水。","example":"Apparently, someone left the window open, because the floor is wet.","example_zh":"看來有人沒關窗，因為地板濕了。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/apparently-01-v1.webp","local_path":"/images/vocabulary/senior/apparently-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-appropriate-01-v1","level":"senior","word":"appropriate","sort_order":1,"sense":"適當的","alt_zh":"高中生穿著包鞋站在實驗桌旁，涼鞋放在鞋櫃裡。","example":"Closed shoes are appropriate for working in the science lab.","example_zh":"包鞋適合在科學實驗室裡穿。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/appropriate-01-v1.webp","local_path":"/images/vocabulary/senior/appropriate-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-associate-01-v1","level":"senior","word":"associate","sort_order":1,"sense":"聯想","alt_zh":"高中生聞著剛烤好的麵包，腦中浮現祖母在廚房烤麵包的畫面。","example":"I associate the smell of fresh bread with my grandmother's kitchen.","example_zh":"新鮮麵包的香味讓我聯想到祖母的廚房。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/associate-01-v1.webp","local_path":"/images/vocabulary/senior/associate-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-circumstance-01-v1","level":"senior","word":"circumstance","sort_order":1,"sense":"情況","alt_zh":"高中生把樂器搬進體育館，門外的舞台正下著大雨。","example":"Because of the circumstances, we moved our outdoor concert into the gym.","example_zh":"由於當時的情況，我們把戶外音樂會移到體育館。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/circumstance-01-v1.webp","local_path":"/images/vocabulary/senior/circumstance-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-comprehensive-01-v1","level":"senior","word":"comprehensive","sort_order":1,"sense":"全面的","alt_zh":"高中生整理一份包含紙類、玻璃、金屬與塑膠回收圖示的指南。","example":"Our class created a comprehensive guide to recycling at school.","example_zh":"我們班製作了一份全面的校園回收指南。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/comprehensive-01-v1.webp","local_path":"/images/vocabulary/senior/comprehensive-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-consequence-01-v1","level":"senior","word":"consequence","sort_order":1,"sense":"後果","alt_zh":"教室水槽的水龍頭持續出水，水漫過水槽流到地板上。","example":"A flooded classroom was the consequence of leaving the tap running.","example_zh":"忘記關水龍頭的後果是教室淹水。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/consequence-01-v1.webp","local_path":"/images/vocabulary/senior/consequence-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-controversy-01-v1","level":"senior","word":"controversy","sort_order":1,"sense":"爭議","alt_zh":"鎮民在老樹旁討論，有人支持保留老樹，有人指著新建築的模型。","example":"The plan to cut down the old tree caused controversy in our town.","example_zh":"砍掉老樹的計畫在我們鎮上引發爭議。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/controversy-01-v1.webp","local_path":"/images/vocabulary/senior/controversy-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-crucial-01-v1","level":"senior","word":"crucial","sort_order":1,"sense":"關鍵的","alt_zh":"高中生在出發前捏著自行車煞車把手，確認輪子停止轉動。","example":"Checking the brakes is crucial before a long bike ride.","example_zh":"長途騎車前檢查煞車至關重要。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/crucial-01-v1.webp","local_path":"/images/vocabulary/senior/crucial-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-demonstrate-01-v1","level":"senior","word":"demonstrate","sort_order":1,"sense":"示範","alt_zh":"老師操作顯微鏡，高中生在旁觀看老師轉動對焦旋鈕。","example":"Our teacher will demonstrate how to use the microscope.","example_zh":"老師會示範如何使用顯微鏡。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/demonstrate-01-v1.webp","local_path":"/images/vocabulary/senior/demonstrate-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-eliminate-01-v1","level":"senior","word":"eliminate","sort_order":1,"sense":"消除","alt_zh":"高中生把午餐裝進可重複使用的餐盒，旁邊空著的塑膠袋架已不再使用。","example":"Reusable lunch boxes help us eliminate disposable plastic bags.","example_zh":"可重複使用的餐盒幫助我們消除對一次性塑膠袋的需求。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/eliminate-01-v1.webp","local_path":"/images/vocabulary/senior/eliminate-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-emerge-01-v1","level":"senior","word":"emerge","sort_order":1,"sense":"浮現","alt_zh":"剛羽化的蝴蝶攀在裂開的蛹殼上，翅膀尚未完全展開。","example":"A butterfly began to emerge from its chrysalis.","example_zh":"一隻蝴蝶開始從蛹中羽化而出。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/emerge-01-v1.webp","local_path":"/images/vocabulary/senior/emerge-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-enormous-01-v1","level":"senior","word":"enormous","sort_order":1,"sense":"巨大的","alt_zh":"巨大的鯨魚在海面下游過，小船上的人顯得很小。","example":"An enormous whale swam beside our small boat.","example_zh":"一頭巨大的鯨魚游在我們的小船旁。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/enormous-01-v1.webp","local_path":"/images/vocabulary/senior/enormous-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-facilitate-01-v1","level":"senior","word":"facilitate","sort_order":1,"sense":"促進","alt_zh":"一名坐輪椅的高中生沿著新坡道前往圖書館入口。","example":"The new ramp will facilitate access to the school library.","example_zh":"新設的坡道將方便大家進入學校圖書館。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/facilitate-01-v1.webp","local_path":"/images/vocabulary/senior/facilitate-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-fundamental-01-v1","level":"senior","word":"fundamental","sort_order":1,"sense":"基本的","alt_zh":"高中生平視量筒的刻度，小心量取實驗所需的液體。","example":"Learning to measure accurately is fundamental to a good science experiment.","example_zh":"學會精確測量是做好科學實驗的基礎。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/fundamental-01-v1.webp","local_path":"/images/vocabulary/senior/fundamental-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-genuine-01-v1","level":"senior","word":"genuine","sort_order":1,"sense":"真正的","alt_zh":"兩名久別重逢的高中生張開雙臂，其中一人露出自然開心的笑容。","example":"Her genuine smile showed how happy she was to see her friend.","example_zh":"她真誠的笑容顯示出見到朋友有多開心。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/genuine-01-v1.webp","local_path":"/images/vocabulary/senior/genuine-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-implement-01-v1","level":"senior","word":"implement","sort_order":1,"sense":"實施","alt_zh":"高中生把新回收桶放到走廊，開始按照圖示分類紙張與瓶罐。","example":"Our school will implement a new recycling program next month.","example_zh":"我們學校下個月將實施新的回收計畫。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/implement-01-v1.webp","local_path":"/images/vocabulary/senior/implement-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-phenomenon-01-v1","level":"senior","word":"phenomenon","sort_order":1,"sense":"現象","alt_zh":"兩名高中生在雨後看見天空中的彩虹，地上仍有水窪。","example":"A rainbow is a natural phenomenon that often appears after rain.","example_zh":"彩虹是一種常在雨後出現的自然現象。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/phenomenon-01-v1.webp","local_path":"/images/vocabulary/senior/phenomenon-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-sophisticated-01-v1","level":"senior","word":"sophisticated","sort_order":1,"sense":"精密的","alt_zh":"機器手臂利用攝影鏡頭辨識輸送帶上的瓶罐，並放進不同的回收箱。","example":"The robot uses a sophisticated camera system to sort recyclable materials.","example_zh":"這台機器人用精密的攝影系統分類可回收物。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/sophisticated-01-v1.webp","local_path":"/images/vocabulary/senior/sophisticated-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-substantial-01-v1","level":"senior","word":"substantial","sort_order":1,"sense":"大量的","alt_zh":"高中生把許多裝滿米、罐頭和麵食的箱子整齊堆好，準備送到收容所。","example":"Our class collected a substantial amount of food for the shelter.","example_zh":"我們班為收容所募集了大量食物。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/substantial-01-v1.webp","local_path":"/images/vocabulary/senior/substantial-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-sustainable-01-v1","level":"senior","word":"sustainable","sort_order":1,"sense":"可持續的","alt_zh":"高中生沿著綠意盎然的自行車道騎車前往學校。","example":"Cycling to school is a sustainable way to travel.","example_zh":"騎自行車上學是一種永續的交通方式。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/sustainable-01-v1.webp","local_path":"/images/vocabulary/senior/sustainable-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-sympathy-01-v1","level":"senior","word":"sympathy","sort_order":1,"sense":"同情","alt_zh":"女孩坐在難過的朋友旁，輕輕把手放在他的肩上；朋友拿著愛犬的照片。","example":"Mia showed sympathy by sitting beside her friend after his dog died.","example_zh":"朋友的狗過世後，米雅坐在他身旁，表達同情與關心。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/sympathy-01-v1.webp","local_path":"/images/vocabulary/senior/sympathy-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-unprecedented-01-v1","level":"senior","word":"unprecedented","sort_order":1,"sense":"史無前例的","alt_zh":"大型校園科展擺滿展示桌，許多高中生帶著作品參展。","example":"The school saw unprecedented participation in this year's science fair.","example_zh":"今年學校科展的參與人數創下空前紀錄。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/unprecedented-01-v1.webp","local_path":"/images/vocabulary/senior/unprecedented-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-alter-01-v1","level":"senior","word":"alter","sort_order":1,"sense":"改變","alt_zh":"高中生在木製橋梁模型上加裝斜撐，桌上放著修改前的草圖。","example":"We had to alter our model bridge to make it stronger.","example_zh":"我們必須修改橋梁模型，讓它更堅固。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/alter-01-v1.webp","local_path":"/images/vocabulary/senior/alter-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-component-01-v1","level":"senior","word":"component","sort_order":1,"sense":"組件","alt_zh":"高中生把電池裝進小型電動模型車的電池槽。","example":"The battery is an essential component of this electric car.","example_zh":"電池是這輛電動車的重要組件。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/component-01-v1.webp","local_path":"/images/vocabulary/senior/component-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-confront-01-v1","level":"senior","word":"confront","sort_order":1,"sense":"面對","alt_zh":"高中生看著操場旁的垃圾，拿起夾子與垃圾袋準備清理。","example":"We must confront the problem of litter in our schoolyard.","example_zh":"我們必須面對校園裡亂丟垃圾的問題。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/confront-01-v1.webp","local_path":"/images/vocabulary/senior/confront-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-convey-01-v1","level":"senior","word":"convey","sort_order":1,"sense":"傳達","alt_zh":"高中生向同學展示海龜與海洋垃圾的圖畫，並指著畫中的塑膠袋。","example":"Her drawing helped convey the importance of protecting sea turtles.","example_zh":"她的畫有助於傳達保護海龜的重要性。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/convey-01-v1.webp","local_path":"/images/vocabulary/senior/convey-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-cooperate-01-v1","level":"senior","word":"cooperate","sort_order":1,"sense":"合作","alt_zh":"四名高中生各扶住桌子的一角，一起把桌子搬過教室門口。","example":"We must cooperate to carry the heavy table into the classroom.","example_zh":"我們必須合作，把沉重的桌子搬進教室。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/cooperate-01-v1.webp","local_path":"/images/vocabulary/senior/cooperate-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-dimension-01-v1","level":"senior","word":"dimension","sort_order":1,"sense":"維度","alt_zh":"高中生用尺測量紙盒的長、寬和高。","example":"We measured each dimension of the box before building the model.","example_zh":"我們製作模型前，先測量盒子的每個尺寸。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/dimension-01-v1.webp","local_path":"/images/vocabulary/senior/dimension-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-distinct-01-v1","level":"senior","word":"distinct","sort_order":1,"sense":"不同的","alt_zh":"兩隻蝴蝶停在花上，一隻有橘色條紋，另一隻有藍色斑點。","example":"The two butterflies have distinct patterns on their wings.","example_zh":"這兩隻蝴蝶翅膀上的花紋明顯不同。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/distinct-01-v1.webp","local_path":"/images/vocabulary/senior/distinct-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-diverse-01-v1","level":"senior","word":"diverse","sort_order":1,"sense":"多元的","alt_zh":"來自不同文化背景的高中生在桌上分享壽司、咖哩、餃子和麵包。","example":"Our class shared dishes from diverse cultures at the school festival.","example_zh":"我們班在校慶時分享來自多元文化的料理。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/diverse-01-v1.webp","local_path":"/images/vocabulary/senior/diverse-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-donate-01-v1","level":"senior","word":"donate","sort_order":1,"sense":"捐贈","alt_zh":"高中生把乾淨的毛衣、圍巾和外套交給社區募集站的志工。","example":"We donate warm clothes to families who need them each winter.","example_zh":"我們每年冬天都捐贈保暖衣物給有需要的家庭。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/donate-01-v1.webp","local_path":"/images/vocabulary/senior/donate-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-efficient-01-v1","level":"senior","word":"efficient","sort_order":1,"sense":"有效率的","alt_zh":"高中生分工傳遞、分類和裝箱，桌邊整齊堆著裝好的書箱。","example":"Our efficient team packed all the books before lunch.","example_zh":"我們這個有效率的團隊在午餐前就打包好所有書籍。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/efficient-01-v1.webp","local_path":"/images/vocabulary/senior/efficient-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-enhance-01-v1","level":"senior","word":"enhance","sort_order":1,"sense":"增強","alt_zh":"高中生專心練習小提琴，老師在旁指導持弓姿勢。","example":"Regular practice can enhance your ability to play the violin.","example_zh":"規律練習能增進你拉小提琴的能力。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/enhance-01-v1.webp","local_path":"/images/vocabulary/senior/enhance-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-forbid-01-v1","level":"senior","word":"forbid","sort_order":1,"sense":"禁止","alt_zh":"博物館導覽員指著禁止觸摸的手掌圖示，高中生把手收回。","example":"The museum rules forbid visitors from touching the paintings.","example_zh":"博物館規定禁止遊客觸摸畫作。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/forbid-01-v1.webp","local_path":"/images/vocabulary/senior/forbid-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-fulfill-01-v1","level":"senior","word":"fulfill","sort_order":1,"sense":"實現","alt_zh":"年輕飛行員穿著制服站在小飛機旁，手裡拿著童年時的飛機模型。","example":"She worked hard to fulfill her dream of becoming a pilot.","example_zh":"她努力實現成為飛行員的夢想。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/fulfill-01-v1.webp","local_path":"/images/vocabulary/senior/fulfill-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-globe-01-v1","level":"senior","word":"globe","sort_order":1,"sense":"地球","alt_zh":"高中生轉動地球儀，用手指著亞洲東側的台灣。","example":"The students used a globe to locate Taiwan.","example_zh":"學生們用地球儀找出台灣的位置。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/globe-01-v1.webp","local_path":"/images/vocabulary/senior/globe-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-guarantee-01-v1","level":"senior","word":"guarantee","sort_order":1,"sense":"保證","alt_zh":"維修師傅把新電池交給顧客，並遞上一張帶有盾牌圖示的保固卡。","example":"The repair shop will guarantee the new battery for one year.","example_zh":"維修店會為這顆新電池提供一年的保固。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/guarantee-01-v1.webp","local_path":"/images/vocabulary/senior/guarantee-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-identical-01-v1","level":"senior","word":"identical","sort_order":1,"sense":"完全相同的","alt_zh":"兩名高中生並肩站著，穿著款式、顏色與細節完全相同的藍色外套。","example":"We wore identical jackets on the school trip.","example_zh":"我們在校外教學時穿著完全相同的外套。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/identical-01-v1.webp","local_path":"/images/vocabulary/senior/identical-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-impose-01-v1","level":"senior","word":"impose","sort_order":1,"sense":"強加","alt_zh":"圖書館員指著損壞的書，高中生把硬幣交到櫃檯。","example":"The school will impose a fine for damaging library books.","example_zh":"學校會對損壞圖書館書籍的人處以罰款。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/impose-01-v1.webp","local_path":"/images/vocabulary/senior/impose-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-indicate-01-v1","level":"senior","word":"indicate","sort_order":1,"sense":"指出","alt_zh":"高中生指著遠處厚重的烏雲，另一人準備把雨傘打開。","example":"The dark clouds indicate that a storm may be approaching.","example_zh":"烏雲顯示暴風雨可能即將來臨。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/indicate-01-v1.webp","local_path":"/images/vocabulary/senior/indicate-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-insight-01-v1","level":"senior","word":"insight","sort_order":1,"sense":"洞察","alt_zh":"高中生從透明花盆看見腐爛的根，恍然大悟地指向積水。","example":"Examining the roots gave us insight into why the plant was dying.","example_zh":"檢查根部讓我們了解這株植物為何逐漸枯萎。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/insight-01-v1.webp","local_path":"/images/vocabulary/senior/insight-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-inspire-01-v1","level":"senior","word":"inspire","sort_order":1,"sense":"啟發","alt_zh":"太空人在學校分享經驗，一名高中生拿著火箭模型，聽得充滿期待。","example":"The astronaut's story helped inspire me to study science.","example_zh":"這位太空人的故事啟發我學習科學。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/inspire-01-v1.webp","local_path":"/images/vocabulary/senior/inspire-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-interpret-01-v1","level":"senior","word":"interpret","sort_order":1,"sense":"解讀","alt_zh":"高中生對照地圖上的橋梁圖示與眼前的木橋。","example":"We learned to interpret the symbols on a hiking map.","example_zh":"我們學會解讀健行地圖上的符號。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/interpret-01-v1.webp","local_path":"/images/vocabulary/senior/interpret-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-isolate-01-v1","level":"senior","word":"isolate","sort_order":1,"sense":"隔離","alt_zh":"高中生把葉片枯黃的植物移到獨立的托盤，與健康盆栽隔開。","example":"We isolate the sick plants to protect the healthy ones.","example_zh":"我們把生病的植物隔離，以保護健康的植物。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/isolate-01-v1.webp","local_path":"/images/vocabulary/senior/isolate-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-justify-01-v1","level":"senior","word":"justify","sort_order":1,"sense":"證明正當","alt_zh":"學生代表向老師展示漏水屋頂的照片，桌上放著修繕模型。","example":"She used photos of the damage to justify replacing the old roof.","example_zh":"她用損壞處的照片證明更換舊屋頂是合理的。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/justify-01-v1.webp","local_path":"/images/vocabulary/senior/justify-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-absolute-01-v1","level":"senior","word":"absolute","sort_order":1,"sense":"絕對的","alt_zh":"考場裡的高中生各自專注寫答案，彼此沒有交談。","example":"The students worked in absolute silence during the exam.","example_zh":"考試期間，學生們在完全安靜的環境中作答。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/absolute-01-v1.webp","local_path":"/images/vocabulary/senior/absolute-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-accent-01-v1","level":"senior","word":"accent","sort_order":1,"sense":"口音","alt_zh":"高中生專心聆聽一位來自澳洲的交流生說話。","example":"Her Australian accent reminded me of my cousin in Sydney.","example_zh":"她的澳洲口音讓我想起住在雪梨的表姊。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/accent-01-v1.webp","local_path":"/images/vocabulary/senior/accent-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-aid-01-v1","level":"senior","word":"aid","sort_order":1,"sense":"援助","alt_zh":"志工把飲水、食物和毯子送到洪水退去後的社區。","example":"Volunteers delivered emergency aid after the flood.","example_zh":"洪水過後，志工運送緊急援助物資。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/aid-01-v1.webp","local_path":"/images/vocabulary/senior/aid-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-aircraft-01-v1","level":"senior","word":"aircraft","sort_order":1,"sense":"飛機","alt_zh":"一架小型螺旋槳飛機在海島跑道上降落。","example":"The small aircraft landed safely on the island.","example_zh":"這架小飛機安全降落在島上。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/aircraft-01-v1.webp","local_path":"/images/vocabulary/senior/aircraft-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-alert-01-v1","level":"senior","word":"alert","sort_order":1,"sense":"警覺的","alt_zh":"戴安全帽的高中生停在路口，仔細觀察左右來車。","example":"Stay alert when you cycle past a busy intersection.","example_zh":"騎車經過繁忙路口時，要保持警覺。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/alert-01-v1.webp","local_path":"/images/vocabulary/senior/alert-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-alien-01-v1","level":"senior","word":"alien","sort_order":1,"sense":"外星人","alt_zh":"友善的綠色外星人站在太空船門口，向兩名高中生揮手。","example":"The friendly alien offered to show us its spaceship.","example_zh":"友善的外星人主動帶我們參觀牠的太空船。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/alien-01-v1.webp","local_path":"/images/vocabulary/senior/alien-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-ally-01-v1","level":"senior","word":"ally","sort_order":1,"sense":"盟友","alt_zh":"老師站在高中生身旁，和他們一起向校方展示回收計畫的模型。","example":"Our class found an ally in the teacher who supported our recycling plan.","example_zh":"我們班找到一位支持回收計畫的老師，成為我們的盟友。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/ally-01-v1.webp","local_path":"/images/vocabulary/senior/ally-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-apparent-01-v1","level":"senior","word":"apparent","sort_order":1,"sense":"明顯的","alt_zh":"高中生在安全圍欄後觀察橋上的缺口和斷裂欄杆。","example":"The damage to the bridge was apparent after the storm.","example_zh":"暴風雨過後，橋梁的損壞十分明顯。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/apparent-01-v1.webp","local_path":"/images/vocabulary/senior/apparent-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-appeal-01-v1","level":"senior","word":"appeal","sort_order":1,"sense":"呼籲","alt_zh":"高中生在社區集會上展示海灘垃圾的照片，邀請大家加入清理活動。","example":"The students appeal to the community for help cleaning the beach.","example_zh":"學生們呼籲社區協助清理海灘。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/appeal-01-v1.webp","local_path":"/images/vocabulary/senior/appeal-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-appoint-01-v1","level":"senior","word":"appoint","sort_order":1,"sense":"任命","alt_zh":"老師把組長徽章交給一名高中生，其他組員在旁微笑。","example":"The teacher will appoint a leader for our science project.","example_zh":"老師會任命一位同學擔任科學專題的組長。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/appoint-01-v1.webp","local_path":"/images/vocabulary/senior/appoint-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-approve-01-v1","level":"senior","word":"approve","sort_order":1,"sense":"批准","alt_zh":"校長看完學生的社團活動計畫，蓋下一個綠色勾號印章。","example":"The principal will approve our plan after checking the budget.","example_zh":"校長檢查預算後，將批准我們的計畫。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/approve-01-v1.webp","local_path":"/images/vocabulary/senior/approve-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-assess-01-v1","level":"senior","word":"assess","sort_order":1,"sense":"評估","alt_zh":"高中生檢查風雨過後倒下的花架和折斷的樹枝，並在夾板上記錄。","example":"We assess the damage before repairing the school garden.","example_zh":"我們修復校園花園前，先評估損壞情況。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/assess-01-v1.webp","local_path":"/images/vocabulary/senior/assess-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-assure-01-v1","level":"senior","word":"assure","sort_order":1,"sense":"保證","alt_zh":"教練把手輕放在緊張選手的肩膀上，鼓勵他準備上跑道。","example":"The coach tried to assure me that I was ready for the race.","example_zh":"教練試著向我保證，我已經準備好參加比賽。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/assure-01-v1.webp","local_path":"/images/vocabulary/senior/assure-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-avenue-01-v1","level":"senior","word":"avenue","sort_order":1,"sense":"大道","alt_zh":"高中生走在兩側排列整齊樹木的寬闊大道旁。","example":"We walked along the tree-lined avenue after school.","example_zh":"放學後，我們沿著綠樹成蔭的大道散步。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/avenue-01-v1.webp","local_path":"/images/vocabulary/senior/avenue-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-billion-01-v1","level":"senior","word":"billion","sort_order":1,"sense":"十億","alt_zh":"高中生看著天文館螢幕上密密麻麻的星點，感受十億的巨大數量。","example":"The museum's computer model showed a billion stars in our galaxy.","example_zh":"博物館的電腦模型呈現了銀河系中十億顆恆星。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/billion-01-v1.webp","local_path":"/images/vocabulary/senior/billion-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-celebrity-01-v1","level":"senior","word":"celebrity","sort_order":1,"sense":"名人","alt_zh":"知名歌手走進校園慈善音樂會，學生拿著相機歡迎。","example":"The celebrity visited our school to support the charity concert.","example_zh":"這位名人到我們學校支持慈善音樂會。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/celebrity-01-v1.webp","local_path":"/images/vocabulary/senior/celebrity-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-civil-01-v1","level":"senior","word":"civil","sort_order":1,"sense":"公民的","alt_zh":"高中生圍著桌上的平等投票與教育圖示討論公民權利。","example":"Our class discussed civil rights during the history lesson.","example_zh":"我們班在歷史課討論公民權利。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/civil-01-v1.webp","local_path":"/images/vocabulary/senior/civil-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-compose-01-v1","level":"senior","word":"compose","sort_order":1,"sense":"作曲","alt_zh":"高中生坐在鋼琴旁，把想出的旋律記在五線譜上。","example":"Lena likes to compose music for the school band.","example_zh":"莉娜喜歡為學校樂團作曲。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/compose-01-v1.webp","local_path":"/images/vocabulary/senior/compose-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-congress-01-v1","level":"senior","word":"congress","sort_order":1,"sense":"國會","alt_zh":"國會議場中，議員在講台上發言，其他議員聆聽討論。","example":"Congress debated the new environmental law for several hours.","example_zh":"國會花了幾個小時辯論新的環境法案。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/congress-01-v1.webp","local_path":"/images/vocabulary/senior/congress-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-considerable-01-v1","level":"senior","word":"considerable","sort_order":1,"sense":"相當大的","alt_zh":"志工在老圖書館裡修補書架、清潔窗戶，房間仍堆著待整理的書箱。","example":"Restoring the old library required considerable time and effort.","example_zh":"修復這座老圖書館需要相當多的時間與心力。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/considerable-01-v1.webp","local_path":"/images/vocabulary/senior/considerable-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-convert-01-v1","level":"senior","word":"convert","sort_order":1,"sense":"轉換","alt_zh":"太陽光照到小型太陽能板，連接的燈泡亮了起來。","example":"The device can convert sunlight into electricity.","example_zh":"這個裝置能把陽光轉換成電能。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/convert-01-v1.webp","local_path":"/images/vocabulary/senior/convert-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-core-01-v1","level":"senior","word":"core","sort_order":1,"sense":"核心","alt_zh":"高中生把代表減少食物浪費的餐盤圖示放在計畫圖的正中央。","example":"At the core of our plan is a desire to reduce food waste.","example_zh":"我們計畫的核心是減少食物浪費。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/core-01-v1.webp","local_path":"/images/vocabulary/senior/core-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-critic-01-v1","level":"senior","word":"critic","sort_order":1,"sense":"評論家","alt_zh":"影評人在電影院裡觀看電影，手裡拿著筆記本記下觀察。","example":"The film critic praised the young director's first movie.","example_zh":"這位影評人讚賞年輕導演的首部電影。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/critic-01-v1.webp","local_path":"/images/vocabulary/senior/critic-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-curve-01-v1","level":"senior","word":"curve","sort_order":1,"sense":"曲線","alt_zh":"湖畔的道路形成一道清楚柔和的彎曲線條。","example":"The road follows a gentle curve around the lake.","example_zh":"道路沿著湖邊緩緩彎曲。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/curve-01-v1.webp","local_path":"/images/vocabulary/senior/curve-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-declare-01-v1","level":"senior","word":"declare","sort_order":1,"sense":"宣布","alt_zh":"評審在舞台上示意獲勝的學生上前領獎，其他人鼓掌。","example":"The judges will declare the winner after the final performance.","example_zh":"評審會在最後一場表演結束後宣布得獎者。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/declare-01-v1.webp","local_path":"/images/vocabulary/senior/declare-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-desperate-01-v1","level":"senior","word":"desperate","sort_order":1,"sense":"絕望的","alt_zh":"高中生拿著狗的照片，焦急地在公園向路人詢問。","example":"We made a desperate search for our missing dog before sunset.","example_zh":"我們在日落前焦急地尋找走失的狗。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/desperate-01-v1.webp","local_path":"/images/vocabulary/senior/desperate-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-economic-01-v1","level":"senior","word":"economic","sort_order":1,"sense":"經濟的","alt_zh":"小鎮新市場裡，商販出售農產品，顧客購物，店家忙碌。","example":"The new market brought economic benefits to the town.","example_zh":"新市場為這個小鎮帶來經濟效益。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/economic-01-v1.webp","local_path":"/images/vocabulary/senior/economic-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-electronic-01-v1","level":"senior","word":"electronic","sort_order":1,"sense":"電子的","alt_zh":"高中生在考試前關閉手機、平板和智慧手錶。","example":"Students must turn off electronic devices during the exam.","example_zh":"考試期間，學生必須關閉電子裝置。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/electronic-01-v1.webp","local_path":"/images/vocabulary/senior/electronic-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-emphasis-01-v1","level":"senior","word":"emphasis","sort_order":1,"sense":"強調","alt_zh":"教練指著戰術板上互相連接的球員圖示，球員圍成一圈聆聽。","example":"The coach placed emphasis on teamwork instead of individual scores.","example_zh":"教練特別強調團隊合作，而非個人得分。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/emphasis-01-v1.webp","local_path":"/images/vocabulary/senior/emphasis-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-equip-01-v1","level":"senior","word":"equip","sort_order":1,"sense":"裝備","alt_zh":"老師把護目鏡發給每一位準備做實驗的高中生。","example":"The school will equip each science team with safety goggles.","example_zh":"學校將為每個科學小組配備護目鏡。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/equip-01-v1.webp","local_path":"/images/vocabulary/senior/equip-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-export-01-v1","level":"senior","word":"export","sort_order":1,"sense":"出口","alt_zh":"茶農把裝有茶葉的木箱送到港口，貨櫃船準備載運。","example":"Local farmers export tea to customers around the world.","example_zh":"當地農民把茶葉出口到世界各地的顧客手中。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/export-01-v1.webp","local_path":"/images/vocabulary/senior/export-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-external-01-v1","level":"senior","word":"external","sort_order":1,"sense":"外部的","alt_zh":"工人站在建築外側，粉刷斑駁的外牆。","example":"The external walls of the building need fresh paint.","example_zh":"這棟建築的外牆需要重新粉刷。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/external-01-v1.webp","local_path":"/images/vocabulary/senior/external-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-extraordinary-01-v1","level":"senior","word":"extraordinary","sort_order":1,"sense":"非凡的","alt_zh":"高中生背對原畫，憑記憶畫出細節相同的作品，同學驚訝地觀看。","example":"Her extraordinary memory helped her recall every detail of the painting.","example_zh":"她非凡的記憶力讓她記起那幅畫的每一個細節。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/extraordinary-01-v1.webp","local_path":"/images/vocabulary/senior/extraordinary-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-faith-01-v1","level":"senior","word":"faith","sort_order":1,"sense":"信仰","alt_zh":"年輕女子坐在安靜的禮拜堂裡，雙手交握，神情平靜。","example":"Her faith brought her comfort during a difficult time.","example_zh":"她的信仰在艱難時刻帶給她安慰。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/faith-01-v1.webp","local_path":"/images/vocabulary/senior/faith-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-fascinate-01-v1","level":"senior","word":"fascinate","sort_order":1,"sense":"迷住","alt_zh":"高中生在水族館凝視透明缸裡發光的水母，神情驚奇。","example":"The glowing jellyfish never fail to fascinate me.","example_zh":"發光的水母總是讓我著迷。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/fascinate-01-v1.webp","local_path":"/images/vocabulary/senior/fascinate-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-fellow-01-v1","level":"senior","word":"fellow","sort_order":1,"sense":"夥伴","alt_zh":"兩名天文社高中生一起調整望遠鏡，準備觀星。","example":"He is a fellow member of our school's astronomy club.","example_zh":"他是我們學校天文社的夥伴。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/fellow-01-v1.webp","local_path":"/images/vocabulary/senior/fellow-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-filter-01-v1","level":"senior","word":"filter","sort_order":1,"sense":"過濾器","alt_zh":"透明濾水器攔住泥沙，上方是混濁水，下方流出較清澈的水。","example":"The filter traps small pieces of dirt in the water.","example_zh":"這個過濾器會攔住水中的細小髒汙。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/filter-01-v1.webp","local_path":"/images/vocabulary/senior/filter-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-finance-01-v1","level":"senior","word":"finance","sort_order":1,"sense":"金融","alt_zh":"年輕學生在小店裡和店主一起整理收支資料與硬幣。","example":"She hopes to study finance and help small businesses manage money.","example_zh":"她希望研讀金融，協助小企業管理資金。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/finance-01-v1.webp","local_path":"/images/vocabulary/senior/finance-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-frequent-01-v1","level":"senior","word":"frequent","sort_order":1,"sense":"頻繁的","alt_zh":"高中生在球場上反覆練習傳球，旁邊放著多顆訓練用球。","example":"Frequent practice helped our team improve its passing skills.","example_zh":"頻繁的練習幫助我們球隊提升傳球技巧。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/frequent-01-v1.webp","local_path":"/images/vocabulary/senior/frequent-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-immigrant-01-v1","level":"senior","word":"immigrant","sort_order":1,"sense":"移民","alt_zh":"新移民店主在剛開幕的麵包店招呼鄰居，家人幫忙擺放麵包。","example":"The new immigrant opened a bakery in our neighborhood.","example_zh":"這位新移民在我們社區開了一間麵包店。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/immigrant-01-v1.webp","local_path":"/images/vocabulary/senior/immigrant-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-inner-01-v1","level":"senior","word":"inner","sort_order":1,"sense":"內在的","alt_zh":"高中生在寧靜的樹林步道上慢慢行走，神情放鬆。","example":"A quiet walk helped her find inner peace after a stressful day.","example_zh":"忙碌緊張的一天後，安靜散步幫助她找回內心的平靜。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/inner-01-v1.webp","local_path":"/images/vocabulary/senior/inner-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-input-01-v1","level":"senior","word":"input","sort_order":1,"sense":"輸入","alt_zh":"高中生在鍵盤上輸入資料，簡單箭頭從鍵盤指向螢幕。","example":"The computer uses input from the keyboard to display the message.","example_zh":"電腦利用鍵盤輸入的資料來顯示訊息。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/input-01-v1.webp","local_path":"/images/vocabulary/senior/input-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-insert-01-v1","level":"senior","word":"insert","sort_order":1,"sense":"插入","alt_zh":"高中生小心把記憶卡插入相機側邊的卡槽。","example":"Insert the memory card into the camera before taking photos.","example_zh":"拍照前，先把記憶卡插進相機。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/insert-01-v1.webp","local_path":"/images/vocabulary/senior/insert-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-insurance-01-v1","level":"senior","word":"insurance","sort_order":1,"sense":"保險","alt_zh":"旅客在機場服務櫃檯出示帶有盾牌圖示的旅遊保險文件，旁邊是行李推車。","example":"Travel insurance helped cover the cost of her lost suitcase.","example_zh":"旅遊保險協助支付她遺失行李的損失。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/insurance-01-v1.webp","local_path":"/images/vocabulary/senior/insurance-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-interact-01-v1","level":"senior","word":"interact","sort_order":1,"sense":"互動","alt_zh":"高中生與藝術家面對面交流，一起揉捏桌上的陶土。","example":"The workshop gives students a chance to interact with visiting artists.","example_zh":"這場工作坊讓學生有機會和來訪的藝術家互動。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/interact-01-v1.webp","local_path":"/images/vocabulary/senior/interact-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-journal-01-v1","level":"senior","word":"journal","sort_order":1,"sense":"期刊","alt_zh":"高中生翻閱一本有海洋研究照片與圖表的科學期刊。","example":"We found an article a