ior/medium-01-v1.webp","local_path":"/images/vocabulary/senior/medium-01-v1.webp","style":"generated-senior-v1","version":1},{"id":"senior-multiple-01-v1","level":"senior","word":"multiple","sort_order":1,"sense":"多重的","alt_zh":"高中生比較桌上四座不同結構的橋梁模型。","example":"We tested multiple designs before choosing the strongest bridge.","example_zh":"我們測試了多種設計，才選出最堅固的橋。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/multiple-01-v1.webp","local_path":"/images/vocabulary/senior/multiple-01-v1.webp","style":"generated-senior-v1","version":1}]$senior_rows$::jsonb) as r(id text,level text,word text,sort_order integer,sense text,alt_zh text,example text,example_zh text,image_url text,local_path text,style text,version integer) on conflict (id) do nothing;
